// src/render-common/buildings/catapult-national-wall-finish.ts
var catapultNationalWallSurface = (nation) => {
  if (nation === "japanese") return "japanese-catapult-stone";
  if (nation === "chinese") return "chinese-red-brick";
  if (["nubian", "persian"].includes(nation)) return "plaster";
  if (nation === "viking") return "wood";
  if (nation === "indigenous") return "indigenous-rubble";
  return "stone";
};
var catapultNationalWallFinish = (nation, detailed) => {
  const parts = [];
  const add11 = (part3) => parts.push({ ...part3, architecture: true, stage: part3.stage ?? 2 });
  const point8 = (angle, y, out = 0) => {
    const radius = catapultShellOuterRadius(nation, angle, y) + out;
    return [Math.sin(angle) * radius, y, Math.cos(angle) * radius];
  };
  const band = (bottom, height2, surface, tint) => add11({
    shape: "catapult-shell-band",
    catapultShellNation: nation,
    catapultShellBand: [bottom, bottom + height2],
    position: [0, bottom + height2 / 2, 0],
    size: [1.7, height2, 1.7],
    surface,
    tint,
    stage: 2
  });
  if (nation === "persian") {
    for (const bottom of [1.13, 1.7]) band(bottom, 0.038, "paint", [0.035, 0.2, 0.43]);
    band(0, 0.16, "cut-stone", [0.86, 0.79, 0.66]);
  }
  if (nation === "nubian") {
    band(0, 0.17, "plaster");
    for (let index2 = 0; index2 < 12; index2++) {
      const angle = index2 * Math.PI / 6, y = CATAPULT_SHAFT_HEIGHT * 0.78;
      if (catapultShellVoid(angle, y)) continue;
      runBetween(
        add11,
        point8(angle, y, -0.055),
        point8(angle, y, 0.085),
        [0.045, 0.045],
        { shape: "cylinder", radialSegments: detailed ? 7 : 4, surface: "wood", stage: 2 }
      );
    }
  }
  if (nation === "chinese") {
    const corners = [
      [0.515, 0, 0.735],
      [0.735, 0, 0.515],
      [0.735, 0, -0.515],
      [0.515, 0, -0.735],
      [-0.515, 0, -0.735],
      [-0.735, 0, -0.515],
      [-0.735, 0, 0.515],
      [-0.515, 0, 0.735]
    ];
    const angles = corners.map((corner) => Math.atan2(corner[0], corner[2]));
    const timber = { surface: "paint", tint: CHINESE_TIMBER, stage: 2 };
    for (const angle of angles) {
      add11({ position: point8(angle, 0.025, 0.012), size: [0.1, 0.05, 0.1], shape: "box", surface: "cut-stone", stage: 1 });
      runBetween(add11, point8(angle, 0.04, 0.012), point8(angle, CATAPULT_SHAFT_HEIGHT - 0.055, 0.012), [0.075, 0.075], timber);
    }
    for (const y of [1.17, CATAPULT_SHAFT_HEIGHT - 0.055]) for (let index2 = 0; index2 < angles.length; index2++)
      runBetween(
        add11,
        point8(angles[index2], y, 0.012),
        point8(angles[(index2 + 1) % angles.length], y, 0.012),
        [0.055, 0.055],
        timber
      );
    for (const sign of [-1, 1]) addBambooPole(
      (part3) => add11({ ...part3, tint: [0.95, 0.95, 1] }),
      [sign * 0.515, CATAPULT_SHAFT_HEIGHT - 0.31, 0.751],
      [sign * 0.28, CATAPULT_SHAFT_HEIGHT - 0.055, 0.751],
      0.038,
      0.2
    );
  }
  if (nation === "japanese") {
    const angles = [Math.PI / 4, Math.PI * 0.75, Math.PI * 1.25, Math.PI * 1.75];
    const bamboo = (part3) => add11({ ...part3, tint: [0.3, 0.32, 0.7] });
    for (const angle of angles) add11({
      position: point8(angle, 0.025, 4e-3),
      size: [0.13, 0.05, 0.13],
      shape: "box",
      surface: "japanese-white-stone",
      stage: 1
    });
    for (const angle of angles) for (const side of [-1, 1]) {
      const from = point8(angle, 0.04, 4e-3), to = point8(angle, CATAPULT_SHAFT_HEIGHT - 0.04, 4e-3);
      for (const end of [from, to]) {
        end[0] += Math.cos(angle) * side * 0.02;
        end[2] -= Math.sin(angle) * side * 0.02;
      }
      addBambooPole(bamboo, from, to, 0.045, side * 0.2);
    }
    for (const y of [0.28, 0.96]) for (let index2 = 0; index2 < angles.length - 1; index2++)
      addBambooPole(bamboo, point8(angles[index2], y, 0.012), point8(angles[index2 + 1], y, 0.012), 0.04, 0.3);
  }
  if (nation === "viking") band(0, 0.24, "stone");
  return parts;
};

