// src/render-common/buildings/catapult-window-profiles.ts
var catapultWindowContour = (style, detailed) => {
  const halfWidth = 0.40625, bottom = -0.4266667, top = 0.4266667;
  if (style === "chinese-round") return Array.from({ length: detailed ? 24 : 12 }, (_, index2) => {
    const angle = index2 / (detailed ? 24 : 12) * Math.PI * 2;
    return [Math.cos(angle) * top, Math.sin(angle) * top];
  });
  if (style === "japanese-shoji") return [
    [-halfWidth, bottom],
    [halfWidth, bottom],
    [halfWidth, top],
    [-halfWidth, top]
  ];
  const spring = 0.03, steps = detailed ? 10 : 6;
  const contour = [[-halfWidth, bottom], [halfWidth, bottom]];
  for (let index2 = 0; index2 <= steps; index2++) {
    const x = Math.cos(index2 / steps * Math.PI);
    let crown2 = Math.sqrt(Math.max(0, 1 - x * x));
    if (style === "persian-pointed") crown2 = Math.sqrt(Math.max(0, 1 - Math.abs(x)));
    contour.push([x * halfWidth, spring + (top - spring) * crown2]);
  }
  return contour;
};

