// src/render-common/buildings/roman-gable-roof.ts
var ROMAN_GABLE_PITCH = 0.54;
var addRomanGableRoof = (part3, detailed, x, y, z, width, depth) => {
  const slope = ROMAN_GABLE_PITCH;
  for (const side of [-1, 1]) {
    part3(
      "roof",
      [x + side * width / 4, y + DMath.tan(slope) * width / 4, z],
      [width / 2 / DMath.cos(slope), 0.065, depth],
      4,
      "box",
      [0, 0, -side * slope]
    );
  }
  part3(
    "roof",
    [x, y + DMath.tan(slope) * width / 2, z],
    [0.12, depth + 0.04, 0.12],
    4,
    "cylinder",
    [Math.PI / 2, 0, 0]
  );
  const rise = DMath.tan(slope) * width / 2;
  for (const end of [-1, 1]) part3(
    "stone",
    [x, y + rise / 2, z + end * (depth / 2 - 0.07)],
    [width - 0.1, rise, 0.08],
    3,
    "gable"
  );
  if (!detailed) return;
  for (const end of [-1, 1]) part3("stone", [x, y + 0.04, z + end * depth / 2], [width, 0.045, 0.055], 4);
};
var createRomanGableRoof = (part3, detailed) => (x, y, z, width, depth) => addRomanGableRoof(part3, detailed, x, y, z, width, depth);

