// src/render-common/buildings/roman-flour-stock.ts
var fitRomanFlourStock = (definition, recipe, detailed) => {
  const slots2 = recipe.parts.filter((part3) => part3.stock?.ware === "flour");
  if (!slots2.length) return;
  const canonical = createWareRecipe("flour", detailed).parts;
  const bottom = Math.min(...canonical.map((part3) => getRomanPartBounds(part3).min[1]));
  const scale2 = WORKER_SCALE / getRomanRecipeFitScale(definition, recipe);
  const keys3 = new Set(slots2.map((part3) => `${part3.stock.kind}:${part3.stock.slot}`));
  recipe.parts = recipe.parts.filter((part3) => part3.stock?.ware !== "flour");
  for (const key5 of keys3) {
    const pieces = slots2.filter((part3) => `${part3.stock.kind}:${part3.stock.slot}` === key5);
    const bounds2 = pieces.map((part3) => getRomanPartBounds(part3));
    const minimum2 = [0, 1, 2].map((axis) => Math.min(...bounds2.map((bound) => bound.min[axis])));
    const maximum2 = [0, 1, 2].map((axis) => Math.max(...bounds2.map((bound) => bound.max[axis])));
    const center = [
      (minimum2[0] + maximum2[0]) / 2,
      minimum2[1] - bottom * scale2,
      (minimum2[2] + maximum2[2]) / 2
    ];
    for (const part3 of canonical) recipe.parts.push({
      ...part3,
      stock: pieces[0].stock,
      position: part3.position.map((value, axis) => center[axis] + value * scale2),
      size: part3.size.map((value) => value * scale2)
    });
  }
};

// src/render-common/buildings/roman-grain-stock.ts
var fitRomanMillGrainStock = (definition, recipe) => {
  if (definition.id !== MILL_TYPE_ID) return;
  const parts = recipe.parts.filter((part3) => part3.stock?.ware === "grain");
  if (!parts.length) return;
  const bounds2 = parts.map((part3) => getRomanPartBounds(part3));
  const minimum2 = [0, 1, 2].map((axis) => Math.min(...bounds2.map((bound) => bound.min[axis])));
  const maximum2 = [0, 1, 2].map((axis) => Math.max(...bounds2.map((bound) => bound.max[axis])));
  const pivot = [
    (minimum2[0] + maximum2[0]) / 2,
    minimum2[1],
    (minimum2[2] + maximum2[2]) / 2
  ];
  const ratio = WORKER_SCALE / getRomanRecipeFitScale(definition, recipe);
  for (const part3 of parts) {
    part3.position = part3.position.map((value, axis) => pivot[axis] + (value - pivot[axis]) * ratio);
    part3.size = part3.size.map((value) => value * ratio);
  }
};

