// src/render-common/buildings/roman-masonry-relief.ts
var masonryCorners = (walls) => {
  const corners = [];
  for (const side of walls.filter((wall) => wall.size[0] === 0.11))
    for (const end of [-1, 1]) {
      const z = side.position[2] + end * side.size[2] / 2;
      const face2 = walls.find(
        (wall) => wall.size[2] === 0.11 && Math.abs(wall.position[2] - z) < 0.12 && Math.abs(wall.position[0] - side.position[0]) <= wall.size[0] / 2 + 0.065 && Math.abs(wall.position[1] - side.position[1]) < (wall.size[1] + side.size[1]) / 2
      );
      if (!face2) continue;
      const bottom = Math.max(
        side.position[1] - side.size[1] / 2,
        face2.position[1] - face2.size[1] / 2
      );
      const top = Math.min(
        side.position[1] + side.size[1] / 2,
        face2.position[1] + face2.size[1] / 2
      );
      if (top - bottom < 0.35) continue;
      corners.push({
        side,
        bottom,
        top,
        xDirection: Math.sign(side.position[0] - face2.position[0]),
        zDirection: end
      });
    }
  return corners.sort(
    (a, b) => b.side.position[2] + b.zDirection * b.side.size[2] / 2 - a.side.position[2] - a.zDirection * a.side.size[2] / 2
  );
};
var addRomanMasonryRelief = ({ detailed, part: part3, parts }) => {
  const walls = parts.filter(
    (wall) => wall.surface === "stone" && wall.stage === 1 && wall.shape === "box" && wall.size[1] > 0.45 && (wall.size[0] === 0.11 || wall.size[2] === 0.11)
  );
  const corners = masonryCorners(walls);
  let blocks = 0;
  for (const [index2, corner] of corners.entries()) {
    if (blocks >= (detailed ? 32 : 2)) break;
    const { bottom, side, top, xDirection, zDirection } = corner;
    const rows = detailed ? Math.min(6, Math.ceil((top - bottom) / 0.24)) : 1;
    const pitch2 = (top - bottom) / rows;
    for (let row3 = 0; row3 < rows; row3++) {
      if (blocks >= (detailed ? 32 : 2)) break;
      const y = bottom + pitch2 * (row3 + 0.5);
      const fraction = (y - side.position[1] + side.size[1] / 2) / side.size[1];
      const scaleZ = 1 + ((side.topScale?.[2] ?? 1) - 1) * fraction;
      const x = side.position[0] + xDirection * side.size[0] / 2 + (side.topOffset?.[0] ?? 0) * fraction;
      const z = side.position[2] + zDirection * side.size[2] * scaleZ / 2 + (side.topOffset?.[2] ?? 0) * fraction;
      const variation = (row3 * 7 + index2 * 11) % 5 / 5;
      part3(
        "stone",
        [x - xDirection * 0.045, y, z - zDirection * 0.045],
        [0.19 + variation * 0.075, Math.min(pitch2 - 0.012, 0.22), 0.25 - variation * 0.055],
        2,
        "stone-block"
      );
      blocks++;
    }
  }
};

