    minX = Math.min(minX, bounds2.min[0]);
    maxX = Math.max(maxX, bounds2.max[0]);
    minZ = Math.min(minZ, bounds2.min[2]);
    maxZ = Math.max(maxZ, bounds2.max[2]);
