  const x = (rail.bounds.min[0] + rail.bounds.max[0]) / 2;
  const y = (rail.bounds.min[1] + rail.bounds.max[1]) / 2, z = rail.bounds.max[2];
  const parts = [...recipe.parts];
  const add11 = (shape, position, size, surface) => parts.push({ shape, position, size, surface, stage: 3, occupationSign: true });
  add11("bevel-box", [x, y - 0.12, z + 0.025], [0.31, 0.18, 0.045], "wood");
