var addPositionedRomanWareStock = (part3, ware2, slot2, kind, center, detailed, yaw2 = 0) => {
  const recipe = createWareRecipe(ware2, detailed);
  const bottom = Math.min(...recipe.parts.map((piece) => getRomanPartBounds(piece).min[1]));
  const cosine = DMath.cos(yaw2), sine = DMath.sin(yaw2);
  const stockPart = withBuildingStock(part3, ware2, slot2, kind);
  for (const piece of recipe.parts) {
    const [x, y, z] = piece.position;
    stockPart(
      piece.surface,
      [
        center[0] + x * cosine + z * sine,
        center[1] + y - bottom,
        center[2] - x * sine + z * cosine
      ],
      piece.size,
      piece.stage,
      piece.shape,
      [piece.rotation?.[0] ?? 0, (piece.rotation?.[1] ?? 0) + yaw2, piece.rotation?.[2] ?? 0],
      piece.tint
    );
  }
};

