var addFarmBarnRoof = ({ part: part3 }) => {
  const width = 1.62, depth = 1.56, pitch2 = 0.64, eave = 1.62;
  const rise = DMath.tan(pitch2) * width / 2;
  for (const side of [-1, 1]) {
    part3(
      "roof",
      [-0.52 + side * width / 4, eave + rise / 2, -0.08],
      [width / 2 / DMath.cos(pitch2), 0.065, depth],
      4,
      "box",
      [0, 0, -side * pitch2]
    );
    part3(
      "stone",
      [-0.52, eave + rise / 2, -0.08 + side * (depth / 2 - 0.07)],
      [width - 0.1, rise, 0.08],
      3,
      "gable"
    );
  }
  part3(
    "roof",
    [-0.52, eave + rise, -0.08],
    [0.12, depth + 0.04, 0.12],
    4,
    "cylinder",
    [Math.PI / 2, 0, 0]
  );
};
var FARM_HARVEST_BUNDLES = [
  [0.4, -0.33, 0.12],
  [0.7, -0.365, 0.24],
  [1, -0.3, -0.19],
  [0.43, 0.36, -0.23],
  [0.74, 0.28, 0.16],
  [1.01, 0.34, -0.13]
];
var addFarmHarvestBay = ({ detailed, part: part3 }) => {
  for (let slot2 = 0; slot2 < 6; slot2++) {
    const stockPart = withBuildingStock(part3, "grain", slot2);
    const [x, z, yaw2] = FARM_HARVEST_BUNDLES[slot2];
    const cosine = DMath.cos(yaw2), sine = DMath.sin(yaw2);
    const bundlePart = (surface, position, size, stage, shape, rotation, tint) => stockPart(
      surface,
      [
        x + (position[0] + 0.73) * cosine + (position[2] - 0.2) * sine,
        position[1],
        z - (position[0] + 0.73) * sine + (position[2] - 0.2) * cosine
      ],
      size,
      stage,
      shape,
      [rotation?.[0] ?? 0, (rotation?.[1] ?? 0) + yaw2, rotation?.[2] ?? 0],
      tint
    );
    addRomanWheatBales(bundlePart, 1, 0.3, detailed, 0, 0.2);
  }
};
