  romanBench(part3, x, z, 0.46, 0.34, 0.5);
  addAmphora(part3, x + 0.1, 0.53, z, detailed, 0.55);
  if (!detailed) return;
  for (const side of [-1, 1]) romanBench(part3, x, z + side * 0.32, 0.46, 0.14, 0.34);
  for (const offset2 of [-0.1, -0.02])
    part3("paint", [x + offset2, 0.56, z + 0.06], [0.04, 0.05, 0.04], 3, "cylinder", void 0, TERRACOTTA3);
  part3("wood", [HALL_RIGHT + 0.11, 0.24, -0.42], [0.14, 0.04, 0.32], 3);
  for (const offset2 of [-0.09, 0.09]) addAmphora(part3, HALL_RIGHT + 0.11, 0.26, -0.42 + offset2, detailed, 0.8);
