var addEquipmentBench = ({ detailed, part: part3 }) => {
  const z = EQUIPMENT_BENCH_Z, left = TAVERN_YARD.minX + 0.22;
  part3("wood", [left + 0.42, 0.32, z], [0.92, 0.05, 0.22], 3);
  for (const x of [left - 0.02, left + 0.86]) part3("wood", [x, 0.25, z], [0.05, 0.14, 0.18], 3);
  TAVERN_INPUT_WARES.forEach((ware2, slot2) => {
    const center = [left + slot2 * 0.16, 0.345, z];
    addPositionedRomanWareStock(part3, ware2, 0, "input", center, detailed || ware2 === "bow", Math.PI / 2);
  });
};
var addRomanTavern = (context) => {
  const { centerX, depth, entryX, height: height2, width } = TAVERN_HALL;
  authorBuildingArchitecture(context.parts, () => {
    romanRoom(context, centerX, 0, width, depth, height2, entryX);
    addUpperStorey(context);
    addStreetCounter(context);
    addInnSign(context);
    romanChimney(context.part, -0.78, -0.42, 2.3);
    addPergola(context);
  });
  addYardFurniture(context);
  addEquipmentBench(context);
};
var isTavernYardDecor = (part3) => {
  if (part3.stock || part3.stage < 2 || part3.position[1] > 1.25) return false;
  if (part3.position[0] < TAVERN_YARD.minX || part3.position[0] - part3.size[0] / 2 < TAVERN_YARD.minX - 0.05) return false;
  return Math.abs(part3.position[2] - EQUIPMENT_BENCH_Z) > 0.13 || part3.position[1] > 0.3;
};

