// src/render-common/buildings/roman-sawmill-timber.ts
var fitRomanSawmillTimber = (definition, recipe, detailed) => {
  if (definition.id !== 33) return;
  const timber = recipe.parts.find((part3) => !part3.stock && part3.surface === "bark" && part3.shape === "cylinder");
  if (!timber) return;
  const [x, , z] = timber.position;
  const table4 = recipe.parts.find((part3) => part3.surface === "wood" && part3.stage === 2 && Math.abs(part3.position[0] - x) < 1e-3 && Math.abs(part3.position[2] - z) < 1e-3 && Math.abs(part3.size[1] - 0.065) < 1e-3);
  if (!table4) return;
  const ratio = WORKER_SCALE / getRomanRecipeFitScale(definition, recipe);
  const canonical = createWareRecipe("logs", detailed).parts;
  const body = canonical.find((part3) => part3.surface === "bark");
  const center = [x, table4.position[1] + table4.size[1] / 2 + body.size[0] * ratio * TIMBER_LOG_LOWER_RADIUS, z];
  recipe.parts = recipe.parts.filter((part3) => !(!part3.stock && (part3.surface === "bark" || part3.surface === "endgrain") && Math.abs(part3.position[0] - x) <= timber.size[0] * 0.55 && Math.abs(part3.position[1] - timber.position[1]) <= timber.size[0] * 0.55 && Math.abs(part3.position[2] - z) <= timber.size[1] * 0.55));
  for (const part3 of canonical) recipe.parts.push({
    ...part3,
    workyardAssembly: "equipment-33",
    position: part3.position.map((value, axis) => center[axis] + value * ratio),
    size: part3.size.map((value) => value * ratio)
  });
};

