// src/render-common/buildings/roman-woodcutter-timber.ts
var fitRomanWoodcutterTimber = (definition, recipe) => {
  if (definition.id !== WOODCUTTER_TYPE_ID) return;
  const diameter = createWareRecipe("logs", true).parts.find((part3) => part3.surface === "bark").size[0];
  const ratio = WORKER_SCALE / getRomanRecipeFitScale(definition, recipe);
  for (let slot2 = 0; slot2 < 6; slot2++) {
    const parts = recipe.parts.filter((part3) => part3.stock?.ware === "logs" && part3.stock.slot === slot2);
    if (!parts.length) continue;
    const bottom = Math.min(...parts.map((part3) => getRomanPartBounds(part3).min[1]));
    const target2 = diameter * ratio * (TIMBER_LOG_LOWER_RADIUS - 0.5 + Math.floor(slot2 / 2) * TIMBER_LOG_VERTICAL_SPAN);
    for (const part3 of parts) part3.position[1] += target2 - bottom;
  }
};

// src/render-common/buildings/sawmill-stock-recipes.ts
var withSawmillStockRecipes = (recipe) => {
  for (const part3 of recipe.parts) {
    const stock = part3.stock;
    if (!stock) continue;
    if (stock.kind === "input" && ["log", "logs"].includes(stock.ware))
      part3.stock = { ...stock, wares: SAWMILL_RECIPES.map((recipe2) => recipe2.input) };
    if (stock.kind !== "input" && ["plank", "planks"].includes(stock.ware))
      part3.stock = { ...stock, wares: SAWMILL_RECIPES.map((recipe2) => recipe2.output) };
  }
  return recipe;
};

// src/render-common/buildings/workyard-assembly.ts
var authorWorkyardAssembly = (parts, assembly, author) => {
  const first = parts.length;
  const result = author();
  for (let index2 = first; index2 < parts.length; index2++) parts[index2].workyardAssembly = assembly;
  return result;
};

