// src/render-common/buildings/chinese-building-towers.ts
var addChineseTowerPavilions = (add11, original, id, detailed) => {
  for (const plan of militaryTowerPlans(id, original)) {
    const tower = {
      detailed,
      form: {
        base: Math.min(0.75, plan.deck * 0.38),
        batter: 0.025,
        depth: plan.depth,
        width: plan.width,
        front: plan.kind === "watch" ? original.door[2] - 0.03 : void 0
      },
      // The watchtower's look-out windows are too small for a soldier leaning on the sill: enlarged downward.
      lookout: id === 4 ? YAGURA_WATCHTOWER_LOOKOUT : void 0,
      plan,
      x: plan.x,
      z: plan.z
    };
    const timberTower = (part3) => {
      if (part3.surface === "gold") return;
      if (part3.surface === "wood") return add11({ ...part3, surface: "paint", tint: CHINESE_TIMBER });
      if (part3.surface === "plaster" || part3.surface === "stone")
        return add11({ ...part3, surface: "plaster", tint: [0.94, 0.91, 0.83] });
      add11(part3);
    };
    addYaguraTower(timberTower, tower);
    for (const window2 of plan.windows) addYaguraWindow(timberTower, tower, window2);
    addYaguraDoorway(timberTower, tower, doorGapOf(original));
    const height2 = 0.92, eave = plan.deck + height2;
    const halfX = plan.width / 2 - 0.07, halfZ = plan.depth / 2 - 0.07;
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      const x = plan.x + sx * halfX, z = plan.z + sz * halfZ;
      add11({
        position: [x, plan.deck + height2 / 2, z],
        radialSegments: detailed ? 10 : 5,
        shape: "cylinder",
        size: [0.075, height2, 0.075],
        stage: 3,
        surface: "paint",
        tint: CHINESE_TIMBER
      });
      addChineseBracket(add11, [x, eave - 0.15, z], 0, detailed, 0.65);
    }
    for (const side of [-1, 1]) add11({
      position: [plan.x, eave - 0.025, plan.z + side * halfZ],
      shape: "box",
      size: [plan.width, 0.065, 0.075],
      stage: 3,
      surface: "paint",
      tint: CHINESE_TIMBER
    });
    const overhang = plan.kind === "corner" || plan.kind === "guard" ? -0.02 : 0.08;
    const roofWidth = plan.width + 2 * overhang, roofDepth = plan.depth + 2 * overhang;
    const width = Math.min(roofWidth, roofDepth), length3 = Math.max(roofWidth, roofDepth);
    const turned2 = roofWidth > roofDepth;
    const roofHeight = Math.max(0.2, Math.min(id === 9 ? 1.1 : 0.85, width * 0.59));
    const centreY = eave + roofHeight * 0.44, sweep = id === 9 ? 0.35 : 0.3;
    const roofPoint3 = (u, v, lift = 0) => {
      const y = centreY + getOccupationRoofHeight("pyramid", u, v, sweep, 0.85) * roofHeight + lift;
      return turned2 ? [plan.x + v * length3, y, plan.z - u * width] : [plan.x + u * width, y, plan.z + v * length3];
    };
    const fasciaSegments = detailed ? 4 : 2;
    for (const side of [-1, 1]) for (let segment2 = 0; segment2 < fasciaSegments; segment2++) {
      const from = -0.5 + segment2 / fasciaSegments, to = -0.5 + (segment2 + 1) / fasciaSegments;
      runBetween(
        add11,
        roofPoint3(from, side * 0.5, -0.035),
        roofPoint3(to, side * 0.5, -0.035),
        [0.055, 0.06],
        { roofSupport: true, stage: 3, surface: "paint", tint: CHINESE_TIMBER }
      );
    }
    addChineseRoof(add11, {
      min: [plan.x - plan.width / 2 - overhang, eave, plan.z - plan.depth / 2 - overhang],
      max: [plan.x + plan.width / 2 + overhang, eave + 0.4, plan.z + plan.depth / 2 + overhang]
    }, 2, detailed, id === 9, "pyramid");
  }
};

// src/render-common/buildings/chinese-cloud-pattern.ts
var CHINESE_CLOUD_OUTLINE = [
  [[-0.48, -0.07], [-0.63, -0.04], [-0.61, 0.16], [-0.45, 0.17]],
  [[-0.45, 0.17], [-0.39, 0.38], [-0.1, 0.36], [-0.08, 0.15]],
  [[-0.08, 0.15], [0.06, 0.35], [0.31, 0.27], [0.26, 0.1]],
  [[0.26, 0.1], [0.49, 0.17], [0.61, -0.04], [0.43, -0.11]],
  [[0.43, -0.11], [0.27, -0.18], [0.07, -0.08], [-0.09, -0.13]],
  [[-0.09, -0.13], [-0.25, -0.22], [-0.36, -0.18], [-0.48, -0.07]]
];
var CHINESE_CLOUD_CURLS = [
  [[-0.46, 0.07], [-0.49, 0.17], [-0.31, 0.18], [-0.31, 0.07]],
  [[-0.31, 0.07], [-0.31, -0.04], [-0.15, -0.05], [-0.12, 0.03]],
  [[0.07, 0.07], [0.19, 0.17], [0.34, 0.07], [0.24, -0.01]]
];
var sampleChineseCloudCurve = ([a, b, c, d], t) => {
  const s = 1 - t;
  return [
    s ** 3 * a[0] + 3 * s * s * t * b[0] + 3 * s * t * t * c[0] + t ** 3 * d[0],
    s ** 3 * a[1] + 3 * s * s * t * b[1] + 3 * s * t * t * c[1] + t ** 3 * d[1]
  ];
};

// src/render-common/buildings/chinese-headquarters-clouds.ts
var addChineseHeadquartersClouds = (add11, detailed) => {
  const slices = detailed ? 7 : 3;
  for (const side of [-1, 1]) {
    const centre = [side * 0.36, 1.75, 0.6165], scaleX = 0.48, scaleY = 0.32;
    const boundary = CHINESE_CLOUD_OUTLINE.flatMap((curve2) => Array.from({ length: slices }, (_, index2) => sampleChineseCloudCurve(curve2, index2 / slices)));
    for (let index2 = 0; index2 < boundary.length; index2++) {
      const a = boundary[index2], b = boundary[(index2 + 1) % boundary.length];
      let ax = a[0] * scaleX, ay = a[1] * scaleY, bx = b[0] * scaleX, by = b[1] * scaleY;
      if ((bx - ax) * -ay - (by - ay) * -ax < 0) [ax, ay, bx, by] = [bx, by, ax, ay];
      const dx = bx - ax, dy = by - ay, length3 = Math.hypot(dx, dy);
      const ux = dx / length3, uy = dy / length3, nx = -uy, ny = ux;
      const mx = (ax + bx) / 2, my = (ay + by) / 2, height2 = -mx * nx - my * ny;
      add11({
        architecture: true,
        position: [
          centre[0] + mx + nx * height2 / 2,
          centre[1] + my + ny * height2 / 2,
          centre[2]
        ],
        rotation: [0, 0, Math.atan2(dy, dx)],
        shape: "cloud-paint",
        size: [length3, height2, 1e-3],
        topOffset: [-mx * ux - my * uy, 0, 0],
        stage: 2,
        surface: "paint",
        tint: [0.78, 0.64, 0.42]
      });
    }
    for (const curve2 of CHINESE_CLOUD_CURLS) for (let index2 = 0; index2 < slices; index2++) {
      const a = sampleChineseCloudCurve(curve2, index2 / slices), b = sampleChineseCloudCurve(curve2, (index2 + 1) / slices);
      const dx = (b[0] - a[0]) * scaleX, dy = (b[1] - a[1]) * scaleY;
      add11({
        architecture: true,
        position: [
          centre[0] + (a[0] + b[0]) * scaleX / 2,
          centre[1] + (a[1] + b[1]) * scaleY / 2,
          centre[2] + 6e-4
        ],
        rotation: [0, 0, Math.atan2(dy, dx)],
        shape: "paint-stroke",
        stage: 2,
        size: [Math.hypot(dx, dy) + 2e-3, 8e-3, 1e-3],
        surface: "paint",
        tint: [0.67, 0.43, 0.15]
      });
    }
  }
};

