// src/render-common/plants/foliage-atlas-layout.ts
var foliageAtlasUv = (rect, [u, v]) => [rect[0] + (rect[2] - rect[0]) * u, rect[1] + (rect[3] - rect[1]) * v];
var foliageCardVertices = (tile) => ({
  positions: tile.outline.map(([u, v]) => [u - tile.pivot[0], v - tile.pivot[1]]),
  uvs: tile.outline.map((point8) => foliageAtlasUv(tile.uvRect, point8))
});
var createFoliageTileLookup = (manifest) => {
  const tiles = new Map(manifest.tiles.map((tile) => [tile.id, tile]));
  return (id) => {
    const tile = tiles.get(id);
    if (!tile) throw new Error(`Unknown foliage atlas tile: ${id}`);
    return tile;
  };
};

// src/render-common/plants/climber-foliage-atlas-manifest.ts
var CLIMBER_FOLIAGE_ATLAS = climber_foliage_atlas_default;
var getClimberFoliageTile = createFoliageTileLookup(CLIMBER_FOLIAGE_ATLAS);
var climberFoliageCardVertices = (id) => foliageCardVertices(getClimberFoliageTile(id));

// src/render-common/plants/climber-foliage-geometry.ts
var add3 = (a, b, scale2 = 1) => [a[0] + b[0] * scale2, a[1] + b[1] * scale2, a[2] + b[2] * scale2];
var blend = (terms) => normalize2(terms.reduce((sum2, [vector, weight]) => add3(sum2, vector, weight), [0, 0, 0]));
var foliageCardFrame = (up, facing2) => {
  const along4 = normalize2(up);
  let side = cross2(along4, facing2);
  if (Math.hypot(...side) < 1e-6) side = cross2(along4, Math.abs(along4[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0]);
  const right = normalize2(side), normal = normalize2(cross2(right, along4));
  return { normal, right, up: along4 };
};
var foliageCardPoseSurface = (card, vertices) => {
  const { positions: outline2, uvs } = vertices;
  const { normal, right, up } = foliageCardFrame(card.up, card.facing);
  const reach = Math.max(...outline2.map(([, v]) => Math.abs(v)), 1e-6);
  const halfWidth = Math.max(...outline2.map(([u]) => Math.abs(u)), 1e-6);
  const curl = card.curl ?? 0;
  const positions = outline2.map(([u, v]) => {
    const along4 = v / reach;
    return add3(add3(add3(card.position, right, u * card.size), up, v * card.size), normal, -curl * along4 * along4);
  });
  const normals = outline2.map(([u, v]) => blend([
    [normal, 1],
    [right, u / halfWidth * 0.45],
    [up, curl / card.size * 2 * v / reach + 0.12]
  ]));
  const indices3 = [];
  for (let index2 = 1; index2 < outline2.length - 1; index2++) indices3.push(0, index2, index2 + 1);
  return { indices: indices3, normals, positions, uvs };
};
var foliageCardSurface = (card) => foliageCardPoseSurface(card, climberFoliageCardVertices(card.tile));
var WHORLS = [
  { count: 5, length: 0.98, open: 1.2, offset: 0, reach: 0.18, rows: 3, rise: 0, tile: "rose-petal-outer", width: 0.98 },
  { count: 5, length: 0.82, open: 0.74, offset: 0.63, reach: 0.11, rows: 2, rise: 0.09, tile: "rose-petal-outer", width: 0.8 },
  { count: 4, length: 0.62, open: 0.3, offset: 0.39, reach: 0.05, rows: 2, rise: 0.17, tile: "rose-petal-inner", width: 0.62 }
];
var tileBox2 = (id) => {
  const tile = getClimberFoliageTile(id), us = tile.outline.map(([u]) => u), vs = tile.outline.map(([, v]) => v);
  return { rect: tile.uvRect, u0: Math.min(...us), u1: Math.max(...us), v0: tile.pivot[1], v1: Math.max(...vs) };
};
var petalNoise = (seed) => {
  const value = Math.sin(seed * 91.7 + 17.3) * 43758.5453;
  return value - Math.floor(value);
};
var appendPetal = (surface, head, frame, whorl, angle, jitter2) => {
  const { normal: axis, right: b1, up: b2 } = frame;
  const outward2 = normalize2(add3(add3([0, 0, 0], b1, Math.cos(angle)), b2, Math.sin(angle)));
  const tangent = normalize2(cross2(axis, outward2));
  const open = whorl.open + (jitter2 - 0.5) * 0.16;
  const direction = normalize2(add3(add3([0, 0, 0], axis, Math.cos(open)), outward2, Math.sin(open)));
  const inward = normalize2(cross2(tangent, direction));
  const length3 = whorl.length * head.radius, width = whorl.width * head.radius;
  const base = add3(add3(head.position, axis, whorl.rise * head.radius), outward2, whorl.reach * head.radius);
  const box4 = tileBox2(whorl.tile), first = surface.positions.length;
  const tipCurl = whorl.open > 1 ? -0.12 : 0.22;
  for (let row3 = 0; row3 < whorl.rows; row3++) for (let column = 0; column < 3; column++) {
    const along4 = row3 / (whorl.rows - 1), across = column - 1;
    const cup2 = across * across * width * 0.34 * (0.35 + along4);
    const point8 = add3(
      add3(add3(add3(base, direction, length3 * along4), tangent, across * width * 0.5), inward, cup2),
      inward,
      tipCurl * along4 * along4 * length3
    );
    surface.positions.push(point8);
    surface.normals.push(blend([[inward, 1], [tangent, -across * 0.55], [direction, -0.15]]));
    const u = box4.u0 + (box4.u1 - box4.u0) * (across + 1) / 2, v = box4.v0 + (box4.v1 - box4.v0) * along4;
    surface.uvs.push([box4.rect[0] + (box4.rect[2] - box4.rect[0]) * u, box4.rect[1] + (box4.rect[3] - box4.rect[1]) * v]);
  }
  for (let row3 = 0; row3 < whorl.rows - 1; row3++) for (let column = 0; column < 2; column++) {
    const at2 = first + row3 * 3 + column;
    surface.indices.push(at2, at2 + 1, at2 + 4, at2, at2 + 4, at2 + 3);
  }
};
var roseHeadSurface = (head) => {
  const surface = { indices: [], normals: [], positions: [], uvs: [] };
  const ring = foliageCardFrame(Math.abs(head.axis[1]) < 0.95 ? [0, 1, 0] : [1, 0, 0], head.axis);
  for (const [whorlIndex, whorl] of WHORLS.entries()) for (let petal = 0; petal < whorl.count; petal++) {
    const jitter2 = petalNoise(head.seed * 31 + whorlIndex * 7 + petal);
    const angle = (petal + whorl.offset + (jitter2 - 0.5) * 0.18) / whorl.count * Math.PI * 2 + head.seed;
    appendPetal(surface, head, ring, whorl, angle, jitter2);
  }
  return surface;
};
var boundsOf = (points, pad = 0) => ({
  max: [0, 1, 2].map((axis) => Math.max(...points.map((point8) => point8[axis])) + pad),
  min: [0, 1, 2].map((axis) => Math.min(...points.map((point8) => point8[axis])) - pad)
});
var climberStemVolumes = (stem, segmentsPerVolume = 3) => {
  const pad = Math.max(stem.radius[0], stem.radius[1]) + 2e-3, volumes = [];
  for (let first = 0; first < stem.points.length - 1; first += segmentsPerVolume)
    volumes.push(boundsOf(stem.points.slice(first, first + segmentsPerVolume + 1), pad));
  return volumes;
};
var foliagePartBounds = (part3) => {
  if (part3.kind === "foliage-card") return boundsOf(foliageCardSurface(part3).positions, 4e-3);
  if (part3.kind === "rose-head") return boundsOf(roseHeadSurface(part3).positions, 4e-3);
  return boundsOf(part3.points, Math.max(part3.radius[0], part3.radius[1]) + 2e-3);
};

// ../island-of-settlers-shared/src/road-plant-items.ts
var plantDecorationContentId = (asset) => {
  let species = asset.species;
  if (asset.palette !== "default") species = `${species}-${asset.palette}`;
  return `plant-${species}-${asset.form}-${asset.potted ? "pot" : "ground"}-${asset.variant}`;
};

