var PLANT_COMPLETION_ITEM_ID_SET = roadDecorationItemIdsReleasedBy("plantCompletion");
var PLANT_COMPLETION_ITEM_IDS = [...PLANT_COMPLETION_ITEM_ID_SET];
var isPlantCompletionAsset = (asset) => PLANT_COMPLETION_ITEM_ID_SET.has(`roadDecoration:${plantDecorationContentId(asset)}:native`);
