// src/render-common/road-decoration-hanging-lanterns.ts
var createHangingLanternRoadRecipe = (nation, detailed) => {
  const originalId = nation === "japanese" ? "japanese-timber-torii" : "chinese-pailou";
  const original = ROAD_DECORATIONS.find((definition2) => definition2.id === originalId);
  const frameParts = nation === "japanese" ? japaneseRoadToriiParts(original, detailed) : chineseRoadPailouParts(original, detailed);
  const beam3 = frameParts.find((part3) => !("kind" in part3) && part3.shape === "bevel-box" && part3.size[0] > original.opening.width && part3.size[1] === 0.17);
  const parts = [], add11 = roadDecorationAdder(parts);
  const suspensions = [];
  const postOffset = nation === "japanese" ? 0.24 : 0.25;
  const height2 = nation === "japanese" ? 0.34 : 0.44;
  const width = nation === "japanese" ? 0.23 : 0.26;
  for (const side of [-1, 1]) {
    const x = side * (original.opening.width / 2 + postOffset), y = beam3.position[1];
    const bearing3 = [x, y, 0], hook = [x, y, 0.38];
    add11({
      shape: "bevel-box",
      position: [x, y, 0.19],
      size: [0.055, 0.065, 0.44],
      surface: "wood",
      tint: [0.62, 0.45, 0.27]
    });
    const braceRise = 0.23, braceRun = 0.3;
    add11({
      shape: "box",
      position: [x, y - braceRise / 2, braceRun / 2],
      rotation: [Math.atan2(braceRun, braceRise), 0, 0],
      size: [0.035, Math.hypot(braceRise, braceRun) + 0.012, 0.035],
      surface: "wood",
      tint: [0.62, 0.45, 0.27]
    });
    const drop = nation === "japanese" ? 0.09 : 0.13;
    const lanternTop = [x, y - drop, hook[2]];
    add11({
      shape: "cylinder",
      position: [x, y - drop / 2, hook[2]],
      size: [9e-3, drop + 0.018, 9e-3],
      radialSegments: detailed ? 6 : 4,
      surface: "iron",
      tint: [0.24, 0.21, 0.17]
    });
    const lantern = {
      shape: nation === "japanese" ? "paper-lantern" : "chinese-lantern",
      position: [x, lanternTop[1] - height2 / 2, lanternTop[2]],
      size: [width, height2, width],
      stage: 4,
      compactGeometry: true,
      surface: "paint"
    };
    parts.push(lantern);
    suspensions.push({ bearing: bearing3, hook, lanternTop, lantern });
  }
  const definition = { ...original, id: `${originalId}-hanging-study` };
  const fittings = { definition, parts, wind: 0 };
  const frame = { definition, parts: frameParts, wind: 0 };
  return { definition, fittings, frame, suspensions };
};

