var createRoadPlantRecipe = (definition, detailed, variant = 0, potted = false) => {
  if (!Number.isInteger(variant) || variant < 0 || variant >= definition.variants)
    throw new Error("Unknown road plant variant");
  if (potted && !["bush", "flower", "column", "bonsai", "topiary"].includes(definition.form))
    throw new Error("Raised-crown road trees require a ground root bed");
  const builder = { parts: [], detailed, seed: variant * 73 + definition.id.length * 17 };
  let base = 0;
  if (potted) base = plantCeramicPot(builder, variant, definition.form === "bonsai");
  if (definition.form === "topiary") topiaryParts(builder, definition, variant, base);
  else if (definition.form === "bonsai") grownRoadTreeParts(builder, definition, variant, base);
  else if (definition.form === "tree" || definition.form === "weeping") {
    treeRoots(builder, 0.15);
    grownRoadTreeParts(builder, definition, variant);
  } else if (definition.form === "palm") palmParts(builder, definition, variant);
  else if (definition.form === "column") {
    columnParts(builder, definition, variant);
    if (base) for (const part3 of builder.parts.slice()) {
      if (part3.surface === "bark" || part3.surface === "leaf") part3.position[1] += base;
    }
  } else shrubParts(builder, definition, variant, base);
  return {
    id: definition.id,
    variant,
    potted,
    form: "roadside",
    flowerColour: builder.flowerColour,
    parts: builder.parts,
    wind: 0
  };
};
var createStandalonePlantRecipe = (definition, detailed, variant = 0) => {
  const natural = { ...definition };
  if (["tree", "weeping"].includes(definition.form)) {
    natural.height *= 1.35;
    natural.crownRadius *= 3;
    natural.crownBase = definition.form === "weeping" ? 0.85 : 1.05;
  } else if (definition.form === "palm") {
    natural.height *= 1.3;
    natural.crownRadius *= 1.55;
  }
  return { ...createRoadPlantRecipe(natural, detailed, variant), form: "standalone" };
};

// src/render-common/road-decoration-plants.ts
var createPlantDecorationRecipe = (definition, detailed) => {
  const asset = definition.plant, species = asset && getRoadPlant(asset.species);
  if (!asset || !species || asset.harvestable !== false) throw new Error("Unknown ornamental plant decoration");
  return asset.form === "standalone" ? createStandalonePlantRecipe(species, detailed, asset.variant) : createRoadPlantRecipe(species, detailed, asset.variant, asset.potted);
};

